-- Aprenda se Divertindo · 74 · Cartões da trilha Policial · parte 3 de 5 (cartões 1000201 a 1000300)
-- Cole no SQL Editor e clique em Run. Pode rodar de novo sem problema. Rode as partes em ordem (a parte 1 cria a tabela).

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 1000201, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quais causas aumentam a pena do tráfico em 1/6 a 2/3?", "verso": "Transnacionalidade, interestadualidade, prevalecer-se de função pública, proximidade de escolas, hospitais, presídios e locais de trabalho coletivo, uso de violência ou arma, envolver criança ou adolescente, financiar o tráfico.", "explicacao": "Lei 11.343/2006, art. 40."}, {"id": 1000202, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Quais as formas de violência doméstica e familiar contra a mulher?", "verso": "Física, psicológica, sexual, patrimonial e moral.", "explicacao": "Lei 11.340/2006, art. 7º."}, {"id": 1000203, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? Nos crimes da Lei Maria da Penha, é possível aplicar os institutos da Lei 9.099 (transação, suspensão do processo).", "verso": "Errado.", "explicacao": "Lei 11.340/2006, art. 41, e Súmula 536 do STJ."}, {"id": 1000204, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Qual a ação penal na lesão corporal contra a mulher em violência doméstica?", "verso": "Pública incondicionada.", "explicacao": "Súmula 542 do STJ e ADI 4.424 do STF."}, {"id": 1000205, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? A autoridade policial pode conceder medida protetiva de afastamento do lar.", "verso": "Certo, em situação de risco atual ou iminente: o delegado, quando o município não for sede de comarca, ou o policial, quando também não houver delegado disponível. O juiz é comunicado em 24 horas.", "explicacao": "Lei 11.340/2006, art. 12-C."}, {"id": 1000206, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Descumprir medida protetiva de urgência é crime?", "verso": "Sim: reclusão de 2 a 5 anos e multa. Só o juiz pode conceder fiança.", "explicacao": "Lei 11.340/2006, art. 24-A (redação da Lei 14.994/2024)."}, {"id": 1000207, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? A Lei Maria da Penha só protege a mulher que mora com o agressor.", "verso": "Errado. Aplica-se a qualquer relação íntima de afeto, independentemente de coabitação.", "explicacao": "Lei 11.340/2006, art. 5º, III, e Súmula 600 do STJ."}, {"id": 1000208, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Nos crimes de violência doméstica contra a mulher, cabe pena só de cesta básica ou multa?", "verso": "Não. É vedada a pena de cesta básica, prestação pecuniária ou substituição que implique pagamento isolado de multa.", "explicacao": "Lei 11.340/2006, art. 17."}, {"id": 1000209, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pares", "frente": "Criança x adolescente no ECA.", "verso": "Criança: até 12 anos incompletos. Adolescente: de 12 a 18 anos.", "explicacao": "Lei 8.069/1990, art. 2º."}, {"id": 1000210, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pares", "frente": "Ato infracional de criança x de adolescente: o que se aplica?", "verso": "Criança: medidas de proteção (art. 101). Adolescente: medidas socioeducativas (art. 112).", "explicacao": "ECA, arts. 105 e 112."}, {"id": 1000211, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Qual o prazo máximo da internação do adolescente?", "verso": "3 anos, com reavaliação no máximo a cada 6 meses. Liberação compulsória aos 21 anos.", "explicacao": "ECA, art. 121, §§ 2º, 3º e 5º."}, {"id": 1000212, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Prazo máximo da internação provisória (antes da sentença):", "verso": "45 dias.", "explicacao": "ECA, arts. 108 e 183."}, {"id": 1000213, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Quais as medidas socioeducativas?", "verso": "Advertência, obrigação de reparar o dano, prestação de serviços à comunidade, liberdade assistida, semiliberdade e internação.", "explicacao": "ECA, art. 112."}, {"id": 1000214, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Corrupção de menores: o que diz a Súmula 500 do STJ?", "verso": "É crime formal: basta a participação do menor no crime, sem prova de que ele foi efetivamente corrompido.", "explicacao": "ECA, art. 244-B, e Súmula 500 do STJ."}, {"id": 1000215, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "O adolescente apreendido em flagrante deve ser conduzido a quem?", "verso": "À autoridade policial competente; a apreensão e o local devem ser comunicados imediatamente ao juiz e à família.", "explicacao": "ECA, arts. 107 e 172."}, {"id": 1000216, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pares", "frente": "Posse x porte ilegal de arma de uso permitido.", "verso": "Posse (art. 12): manter a arma dentro de casa ou no local de trabalho, sendo o responsável. Porte (art. 14): levar a arma fora desses locais.", "explicacao": "Lei 10.826/2003. Posse: detenção de 1 a 3 anos. Porte: reclusão de 2 a 4 anos."}, {"id": 1000217, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a pena da posse ou porte de arma de uso restrito?", "verso": "Reclusão de 3 a 6 anos e multa.", "explicacao": "Lei 10.826/2003, art. 16. Se for de uso proibido: 4 a 12 anos (§ 2º)."}, {"id": 1000218, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "O que é disparo de arma de fogo como crime?", "verso": "Disparar arma ou acionar munição em lugar habitado ou adjacências, em via pública ou em direção a ela, desde que não seja para praticar outro crime.", "explicacao": "Lei 10.826/2003, art. 15."}, {"id": 1000219, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a idade mínima para adquirir arma de fogo?", "verso": "25 anos.", "explicacao": "Lei 10.826/2003, art. 28 (com exceções para integrantes das forças de segurança)."}, {"id": 1000220, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Comércio ilegal e tráfico internacional de arma são hediondos?", "verso": "Sim, assim como a posse ou porte de arma de uso proibido.", "explicacao": "Lei 8.072/1990, art. 1º, parágrafo único."}, {"id": 1000221, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Qual a pena base do crime de tortura?", "verso": "Reclusão de 2 a 8 anos.", "explicacao": "Lei 9.455/1997, art. 1º."}, {"id": 1000222, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Quem se omite diante da tortura, tendo o dever de evitá-la, responde como?", "verso": "Detenção de 1 a 4 anos.", "explicacao": "Lei 9.455/1997, art. 1º, § 2º."}, {"id": 1000223, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Qual o efeito da condenação por tortura para o servidor?", "verso": "Perda do cargo, função ou emprego público e interdição para seu exercício pelo dobro do prazo da pena aplicada. É efeito automático.", "explicacao": "Lei 9.455/1997, art. 1º, § 5º."}, {"id": 1000224, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Em que regime se inicia a pena por tortura (fora a omissão)?", "verso": "Regime fechado.", "explicacao": "Lei 9.455/1997, art. 1º, § 7º."}, {"id": 1000225, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "A lei de tortura alcança crime cometido no exterior?", "verso": "Sim, se a vítima for brasileira ou o agente estiver em local sob jurisdição brasileira.", "explicacao": "Lei 9.455/1997, art. 2º."}, {"id": 1000226, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Cite crimes hediondos do CP.", "verso": "Homicídio qualificado e o praticado em atividade típica de grupo de extermínio, feminicídio, latrocínio, extorsão mediante sequestro, estupro e estupro de vulnerável, epidemia com resultado morte, entre outros.", "explicacao": "Lei 8.072/1990, art. 1º."}, {"id": 1000227, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Quais crimes são equiparados a hediondos pela Constituição?", "verso": "Tortura, tráfico de drogas e terrorismo.", "explicacao": "CF, art. 5º, XLIII."}, {"id": 1000228, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pares", "frente": "Progressão de regime: primário x reincidente em hediondo (sem morte).", "verso": "Primário: 40% da pena. Reincidente em hediondo: 60%.", "explicacao": "LEP, art. 112, V e VII (Pacote Anticrime). Com resultado morte: 50% (primário) e 70% (reincidente)."}, {"id": 1000229, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Condenado por hediondo pode receber indulto?", "verso": "Não. Hediondos e equiparados são insuscetíveis de anistia, graça e indulto, e de fiança.", "explicacao": "Lei 8.072/1990, art. 2º."}, {"id": 1000230, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "O que é organização criminosa?", "verso": "Associação de 4 ou mais pessoas, estruturalmente ordenada, com divisão de tarefas, para obter vantagem mediante infrações com pena máxima superior a 4 anos ou de caráter transnacional.", "explicacao": "Lei 12.850/2013, art. 1º, § 1º."}, {"id": 1000231, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pares", "frente": "Organização criminosa x associação criminosa.", "verso": "Organização: 4 ou mais pessoas, estrutura ordenada e divisão de tarefas (Lei 12.850). Associação: 3 ou mais pessoas para cometer crimes (CP, art. 288).", "explicacao": "Diferença no número mínimo e na estrutura."}, {"id": 1000232, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Quais meios de obtenção de prova a Lei 12.850 prevê?", "verso": "Colaboração premiada, captação ambiental, ação controlada, acesso a registros e dados, interceptação, afastamento de sigilos, infiltração de agentes e cooperação entre instituições.", "explicacao": "Lei 12.850/2013, art. 3º."}, {"id": 1000233, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "A ação controlada precisa de autorização judicial?", "verso": "Não precisa de autorização, mas deve ser previamente comunicada ao juiz, que pode estabelecer limites.", "explicacao": "Lei 12.850/2013, art. 8º, § 1º."}, {"id": 1000234, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Qual o elemento subjetivo exigido nos crimes de abuso de autoridade?", "verso": "Finalidade específica de prejudicar outrem, beneficiar a si ou a terceiro, ou por mero capricho ou satisfação pessoal.", "explicacao": "Lei 13.869/2019, art. 1º, § 1º."}, {"id": 1000235, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "certo_errado", "frente": "Certo ou errado? A divergência na interpretação da lei ou na avaliação de fatos e provas configura abuso de autoridade.", "verso": "Errado. Não configura, por si só (vedação ao crime de hermenêutica).", "explicacao": "Lei 13.869/2019, art. 1º, § 2º."}, {"id": 1000236, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Qual a ação penal nos crimes de abuso de autoridade?", "verso": "Pública incondicionada, admitida a ação privada subsidiária.", "explicacao": "Lei 13.869/2019, art. 3º."}, {"id": 1000237, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "A perda do cargo por abuso de autoridade é automática?", "verso": "Não. Depende de reincidência em crime de abuso e deve ser declarada motivadamente na sentença.", "explicacao": "Lei 13.869/2019, art. 4º, parágrafo único."}, {"id": 1000238, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Constranger o preso, com violência, grave ameaça ou redução da capacidade de resistência, a exibir o corpo à curiosidade pública é crime?", "verso": "Sim, abuso de autoridade.", "explicacao": "Lei 13.869/2019, art. 13, I."}, {"id": 1000239, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "pergunta", "frente": "Injúria racial: como está tratada hoje?", "verso": "Como crime de racismo, na Lei 7.716/1989 (art. 2º-A): imprescritível e inafiançável, com pena de reclusão de 2 a 5 anos.", "explicacao": "Lei 14.532/2023."}, {"id": 1000240, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "certo_errado", "frente": "Certo ou errado? O crime de racismo prescreve em 20 anos.", "verso": "Errado. É imprescritível.", "explicacao": "CF, art. 5º, XLII."}, {"id": 1000241, "trilha": "policial", "materia": "leg", "assunto": "Lei do delegado", "tipo": "pergunta", "frente": "Qual a natureza das funções do delegado de polícia?", "verso": "Funções de polícia judiciária e apuração de infrações penais, de natureza jurídica, essenciais e exclusivas de Estado.", "explicacao": "Lei 12.830/2013, art. 2º."}, {"id": 1000242, "trilha": "policial", "materia": "leg", "assunto": "Lei do delegado", "tipo": "pergunta", "frente": "O inquérito pode ser avocado ou redistribuído livremente?", "verso": "Não. Só por superior hierárquico, por despacho fundamentado, por motivo de interesse público ou descumprimento de procedimentos.", "explicacao": "Lei 12.830/2013, art. 2º, § 4º."}, {"id": 1000243, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Qual a pena do homicídio culposo na direção de veículo?", "verso": "Detenção de 2 a 4 anos e suspensão ou proibição da habilitação.", "explicacao": "CTB, art. 302."}, {"id": 1000244, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Homicídio culposo no trânsito com motorista embriagado: qual a pena?", "verso": "Reclusão de 5 a 8 anos.", "explicacao": "CTB, art. 302, § 3º."}, {"id": 1000245, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "O que configura o crime de embriaguez ao volante?", "verso": "Conduzir veículo com capacidade psicomotora alterada por álcool (6 decigramas ou mais por litro de sangue, ou 0,3 mg por litro de ar alveolar) ou outra substância psicoativa.", "explicacao": "CTB, art. 306. Pena de detenção de 6 meses a 3 anos."}, {"id": 1000246, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "O que é o crime de “racha”?", "verso": "Participar, em via pública, de corrida, disputa ou competição não autorizada, gerando situação de risco.", "explicacao": "CTB, art. 308."}, {"id": 1000247, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "certo_errado", "frente": "Certo ou errado? Ao condutor que presta pronto e integral socorro à vítima não se imporá prisão em flagrante nem fiança.", "verso": "Certo.", "explicacao": "CTB, art. 301."}, {"id": 1000248, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Quais são as faltas graves cometidas pelo preso?", "verso": "Fuga, incitar ou participar de movimento para subverter a ordem, possuir instrumento capaz de ofender, ter aparelho celular, provocar acidente de trabalho, descumprir condições do regime aberto, não se submeter às ordens, recusar identificação genética.", "explicacao": "LEP, art. 50."}, {"id": 1000249, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Como funciona a remição pelo estudo e pelo trabalho?", "verso": "Trabalho: 1 dia de pena a cada 3 dias de trabalho. Estudo: 1 dia a cada 12 horas de frequência escolar, divididas em no mínimo 3 dias.", "explicacao": "LEP, art. 126."}, {"id": 1000250, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual a duração máxima do regime disciplinar diferenciado (RDD)?", "verso": "Até 2 anos, sem prejuízo de repetição por nova falta grave da mesma espécie.", "explicacao": "LEP, art. 52, I (Pacote Anticrime)."}, {"id": 1000251, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "A falta grave interrompe o prazo para progressão de regime?", "verso": "Sim. O prazo recomeça a partir da falta.", "explicacao": "LEP, art. 112, § 6º, e Súmula 534 do STJ."}, {"id": 1000252, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "certo_errado", "frente": "Certo ou errado? A falta grave interrompe o prazo para obter livramento condicional.", "verso": "Errado.", "explicacao": "Súmula 441 do STJ."}, {"id": 1000253, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Depois da Lei 14.843/2024, a saída temporária ficou restrita a quê?", "verso": "À frequência a curso supletivo profissionalizante, de ensino médio ou superior, por condenados no semiaberto, pelo tempo necessário às atividades escolares.", "explicacao": "LEP, arts. 122 e 124. Acabaram as saídas para visitar a família."}, {"id": 1000254, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "pergunta", "frente": "Quais as três fases clássicas da lavagem de dinheiro?", "verso": "Colocação (placement), ocultação ou dissimulação (layering) e integração.", "explicacao": "Doutrina sobre a Lei 9.613/1998."}, {"id": 1000255, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "certo_errado", "frente": "Certo ou errado? Desde a Lei 12.683/2012, qualquer infração penal pode ser antecedente da lavagem.", "verso": "Certo. Acabou o rol taxativo de crimes antecedentes.", "explicacao": "Lei 9.613/1998, art. 1º."}, {"id": 1000256, "trilha": "policial", "materia": "leg", "assunto": "Terrorismo", "tipo": "certo_errado", "frente": "Certo ou errado? Manifestações sociais e reivindicatórias podem ser enquadradas como terrorismo.", "verso": "Errado. A lei exclui expressamente a conduta individual ou coletiva em manifestações políticas, movimentos sociais, sindicais ou religiosos.", "explicacao": "Lei 13.260/2016, art. 2º, § 2º."}, {"id": 1000257, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "certo_errado", "frente": "Certo ou errado? A tentativa de contravenção penal é punível.", "verso": "Errado.", "explicacao": "Decreto-Lei 3.688/1941, art. 4º."}, {"id": 1000258, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "pergunta", "frente": "Qual a pena máxima de prisão simples nas contravenções?", "verso": "5 anos.", "explicacao": "LCP, art. 10."}, {"id": 1000259, "trilha": "policial", "materia": "leg", "assunto": "Crimes ambientais", "tipo": "pergunta", "frente": "Pessoa jurídica pode responder por crime ambiental?", "verso": "Sim, administrativa, civil e penalmente.", "explicacao": "CF, art. 225, § 3º, e Lei 9.605/1998, art. 3º."}, {"id": 1000260, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "A partir de que idade a pessoa é idosa pelo Estatuto?", "verso": "60 anos.", "explicacao": "Lei 10.741/2003, art. 1º."}, {"id": 1000261, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Qual a ação penal nos crimes do Estatuto da Pessoa Idosa?", "verso": "Pública incondicionada.", "explicacao": "Lei 10.741/2003, art. 95."}, {"id": 1000262, "trilha": "policial", "materia": "leg", "assunto": "Identificação criminal", "tipo": "pergunta", "frente": "Quem já é civilmente identificado pode ser identificado criminalmente?", "verso": "Só nas hipóteses da lei: documento rasurado ou insuficiente, documentos conflitantes, essencial às investigações por decisão judicial, entre outras.", "explicacao": "CF, art. 5º, LVIII, e Lei 12.037/2009, art. 3º."}, {"id": 1000263, "trilha": "policial", "materia": "leg", "assunto": "Interceptação", "tipo": "pergunta", "frente": "Interceptar comunicações sem autorização judicial é crime?", "verso": "Sim: reclusão de 2 a 4 anos e multa.", "explicacao": "Lei 9.296/1996, art. 10."}, {"id": 1000264, "trilha": "policial", "materia": "leg", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Composição civil dos danos homologada: qual o efeito na ação privada ou condicionada?", "verso": "Acarreta renúncia ao direito de queixa ou representação.", "explicacao": "Lei 9.099/1995, art. 74, parágrafo único."}, {"id": 1000265, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "certo_errado", "frente": "Certo ou errado? Arma com registro vencido configura crime de posse ilegal.", "verso": "Errado, segundo o STJ: é infração administrativa.", "explicacao": "STJ, APn 686 e julgados posteriores, para arma de uso permitido."}, {"id": 1000266, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quem pode ser preso em flagrante pelo porte para consumo pessoal?", "verso": "Ninguém. Não se impõe prisão em flagrante; o autor é encaminhado ao juízo ou assina termo de compromisso.", "explicacao": "Lei 11.343/2006, art. 48, § 2º."}, {"id": 1000267, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "O laudo de constatação da droga basta para prender em flagrante?", "verso": "Sim. Para o auto de prisão em flagrante basta o laudo de constatação da natureza e quantidade, por perito oficial ou pessoa idônea.", "explicacao": "Lei 11.343/2006, art. 50, § 1º."}, {"id": 1000268, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Em quanto tempo o adolescente apreendido deve ser liberado ou apresentado ao MP?", "verso": "A autoridade policial deve apresentá-lo ao MP de imediato ou, não sendo possível, em até 24 horas.", "explicacao": "ECA, art. 175."}, {"id": 1000269, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "certo_errado", "frente": "Certo ou errado? O adolescente pode ser transportado em compartimento fechado de viatura em condições que atentem contra sua dignidade.", "verso": "Errado.", "explicacao": "ECA, art. 178."}, {"id": 1000270, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pares", "frente": "Tortura-prova, tortura-crime e tortura-discriminação.", "verso": "Prova: para obter informação, declaração ou confissão. Crime: para provocar ação ou omissão criminosa. Discriminação: em razão de discriminação racial ou religiosa.", "explicacao": "Lei 9.455/1997, art. 1º, I, a, b e c."}, {"id": 1000271, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "A Lei Maria da Penha protege mulheres trans?", "verso": "Sim, segundo o STJ (REsp 1.977.124/SP, 2022).", "explicacao": "Gênero, não sexo biológico, é o critério de proteção."}, {"id": 1000272, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Qual a pena de promover, constituir ou integrar organização criminosa?", "verso": "Reclusão de 3 a 8 anos e multa.", "explicacao": "Lei 12.850/2013, art. 2º."}, {"id": 1000273, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Decretar prisão em manifesta desconformidade com a lei é crime de abuso?", "verso": "Sim.", "explicacao": "Lei 13.869/2019, art. 9º."}, {"id": 1000274, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual a progressão de regime para crime cometido com violência ou grave ameaça por primário?", "verso": "25% da pena.", "explicacao": "LEP, art. 112, III. Sem violência, primário: 16%."}, {"id": 1000275, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "certo_errado", "frente": "Certo ou errado? O tráfico privilegiado (art. 33, § 4º, da Lei de Drogas) é crime hediondo.", "verso": "Errado.", "explicacao": "STF (HC 118.533) e Lei 7.210/1984, art. 112, § 5º."}, {"id": 1000276, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O que é poder de polícia?", "verso": "Atividade da Administração que limita ou disciplina direito, interesse ou liberdade, em razão do interesse público.", "explicacao": "CTN, art. 78."}, {"id": 1000277, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "Quais os atributos do poder de polícia?", "verso": "Discricionariedade, autoexecutoriedade e coercibilidade.", "explicacao": "Mnemônico DAC."}, {"id": 1000278, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "Quais os ciclos do poder de polícia?", "verso": "Ordem, consentimento, fiscalização e sanção.", "explicacao": "Doutrina. O STF admite delegar consentimento e fiscalização a estatais de direito privado (RE 633.782)."}, {"id": 1000279, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pares", "frente": "Poder hierárquico x poder disciplinar.", "verso": "Hierárquico: organizar, ordenar, rever, delegar e avocar dentro da estrutura. Disciplinar: apurar infrações e aplicar penalidades a servidores e a quem tem vínculo especial.", "explicacao": "Doutrina de Direito Administrativo."}, {"id": 1000280, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pares", "frente": "Excesso de poder x desvio de finalidade.", "verso": "Excesso: o agente vai além da sua competência. Desvio: age dentro da competência, mas com finalidade diversa da prevista em lei.", "explicacao": "São as duas espécies de abuso de poder."}, {"id": 1000281, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O que não pode ser objeto de delegação (Lei 9.784)?", "verso": "Edição de atos normativos, decisão de recursos administrativos e matérias de competência exclusiva.", "explicacao": "Lei 9.784/1999, art. 13."}, {"id": 1000282, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quais os elementos (requisitos) do ato administrativo?", "verso": "Competência, finalidade, forma, motivo e objeto.", "explicacao": "Mnemônico COFIFOMOB. Competência, finalidade e forma são vinculados."}, {"id": 1000283, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quais os atributos do ato administrativo?", "verso": "Presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade.", "explicacao": "Mnemônico PATI."}, {"id": 1000284, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Anulação x revogação.", "verso": "Anulação: por ilegalidade, pela Administração ou pelo Judiciário, com efeitos retroativos (ex tunc). Revogação: por conveniência e oportunidade, só pela Administração, efeitos a partir de então (ex nunc).", "explicacao": "Súmula 473 do STF."}, {"id": 1000285, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Qual o prazo para a Administração anular atos que beneficiam o administrado de boa-fé?", "verso": "5 anos.", "explicacao": "Lei 9.784/1999, art. 54."}, {"id": 1000286, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "O que diz a teoria dos motivos determinantes?", "verso": "Se o ato foi motivado, sua validade fica vinculada à veracidade dos motivos declarados, mesmo que a motivação não fosse obrigatória.", "explicacao": "Doutrina e jurisprudência."}, {"id": 1000287, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Ato vinculado x ato discricionário.", "verso": "Vinculado: a lei fixa todos os elementos, sem margem de escolha. Discricionário: a lei deixa margem de conveniência e oportunidade quanto ao motivo e ao objeto.", "explicacao": "O mérito administrativo existe só no ato discricionário."}, {"id": 1000288, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz a Súmula Vinculante 13?", "verso": "Proíbe o nepotismo: nomear cônjuge, companheiro ou parente até o 3º grau da autoridade nomeante ou de servidor em cargo de direção, chefia ou assessoramento, para cargo em comissão ou função de confiança.", "explicacao": "Súmula Vinculante 13 do STF."}, {"id": 1000289, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais os princípios do art. 37 da Constituição?", "verso": "Legalidade, impessoalidade, moralidade, publicidade e eficiência.", "explicacao": "LIMPE. A eficiência entrou com a EC 19/1998."}, {"id": 1000290, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pares", "frente": "Legalidade para o particular x para a Administração.", "verso": "Particular: pode fazer tudo o que a lei não proíbe. Administração: só pode fazer o que a lei autoriza.", "explicacao": "Princípio da legalidade estrita."}, {"id": 1000291, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pares", "frente": "Descentralização x desconcentração.", "verso": "Descentralização: transfere a atividade para outra pessoa jurídica (autarquia, empresa pública…). Desconcentração: distribui competências entre órgãos da mesma pessoa, com hierarquia.", "explicacao": "Mnemônico: desCOncentração = COmpetências internas."}, {"id": 1000292, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "Quais entidades compõem a Administração indireta?", "verso": "Autarquias, fundações públicas, empresas públicas e sociedades de economia mista.", "explicacao": "Decreto-Lei 200/1967, art. 4º."}, {"id": 1000293, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pares", "frente": "Empresa pública x sociedade de economia mista.", "verso": "Empresa pública: capital 100% público, qualquer forma societária. Economia mista: maioria do capital votante público, sempre sociedade anônima.", "explicacao": "Lei 13.303/2016."}, {"id": 1000294, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "Autarquia tem personalidade jurídica de direito público ou privado?", "verso": "De direito público, criada por lei específica.", "explicacao": "CF, art. 37, XIX."}, {"id": 1000295, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Qual teoria fundamenta a responsabilidade objetiva do Estado?", "verso": "Teoria do risco administrativo, que admite excludentes (culpa exclusiva da vítima, caso fortuito, força maior, fato de terceiro).", "explicacao": "CF, art. 37, § 6º."}, {"id": 1000296, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "A vítima pode processar diretamente o agente público que causou o dano?", "verso": "Não. Deve acionar o Estado, que tem ação de regresso contra o agente em caso de dolo ou culpa.", "explicacao": "STF, Tema 940 (dupla garantia)."}, {"id": 1000297, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "O Estado responde pela morte de preso sob sua custódia?", "verso": "Sim, objetivamente, quando descumprido seu dever de proteção.", "explicacao": "STF, Tema 592 (RE 841.526)."}, {"id": 1000298, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "pergunta", "frente": "Quais as espécies de improbidade administrativa?", "verso": "Enriquecimento ilícito (art. 9º), lesão ao erário (art. 10) e atentado aos princípios (art. 11).", "explicacao": "Lei 8.429/1992."}, {"id": 1000299, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "certo_errado", "frente": "Certo ou errado? Após a Lei 14.230/2021, existe improbidade culposa.", "verso": "Errado. Todas as modalidades exigem dolo.", "explicacao": "Lei 8.429/1992, art. 1º, §§ 1º a 3º."}, {"id": 1000300, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "certo_errado", "frente": "Certo ou errado? A ação de improbidade tem natureza penal.", "verso": "Errado. Tem natureza civil, sem prejuízo da ação penal cabível.", "explicacao": "CF, art. 37, § 4º."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select count(*) as cartoes_policial_no_banco from public.cartoes where trilha = 'policial' and ativa;
